if(!secret){let un="unknown";try{un=ZenhUi().username}catch{}
secret=`zcode-credential-fallback:${ZenhPf()}:${ZenhH()}:${un}`}
const dkey=ZenhHa("sha256").update(secret).digest();
const dcp=ZenhDc("aes-256-gcm",dkey,Buffer.from(parts[0],"base64url"));
dcp.setAuthTag(Buffer.from(parts[1],"base64url"));
const pt=Buffer.concat([dcp.update(Buffer.from(parts[2],"base64url")),dcp.final()]).toString("utf-8");
cred[ck]=pt;
}catch{cred[ck]=""}
}else cred[ck]=cv;}
return cred;}
